#include <cstddef>

void reverseInPlace(char* text)
{
    std::size_t length{ 0 };
    while (text[length] != '\0')
    {
        ++length;
    }
    if (length == 0)
    {
        return;
    }
    std::size_t left{ 0 };
    std::size_t right{ length - 1 };
    while (left < right)
    {
        const char temp{ text[left] };
        text[left] = text[right];
        text[right] = temp;
        ++left;
        --right;
    }
}

unitTests:
TEST("odd length") { char s[]{ "hello" }; reverseInPlace(s); CHECK_EQ(std::string{ s }, "olleh"); }
TEST("even length") { char s[]{ "abcd" }; reverseInPlace(s); CHECK_EQ(std::string{ s }, "dcba"); }
TEST("one character and none") { char one[]{ "x" }; reverseInPlace(one); CHECK_EQ(std::string{ one }, "x"); char none[]{ "" }; reverseInPlace(none); CHECK_EQ(std::string{ none }, ""); }

